function overview(){const done=activityDefinitions.filter(a=>status(a.id,state)[1]==='done').length;return `<div class="intro"><div class="section-title"><div><h2>Your deal, at a glance</h2><p>Everything moving forward. Every decision in context.</p></div><span class="small">Updated just now</span></div></div><div class="summary-strip"><div class="metric"><span class="eyebrow">Deal size</span><strong>$250<span style="font-size:15px">M</span></strong><span class="small">Target financing</span></div><div class="metric"><span class="eyebrow">Activities</span><strong>${done}<span style="font-size:15px;color:#99a5b7"> / ${activityDefinitions.length}</span></strong><span class="small">Reviewed or complete</span></div><div class="metric"><span class="eyebrow">Target close</span><strong>18 Dec</strong><span class="small">2026 · In preparation</span></div></div>${!state.preferred?`<div class="attention">${icon('info')}<div><strong>A decision will move this deal forward</strong><p>Select a preferred structure to complete the memo recommendation.</p></div>${btn('go:structure','Review structures →')}</div>`:''}<div class="section-title"><h3>Deal journey</h3><span class="small">${activityDefinitions.length} connected activities</span></div><div class="activity-grid">${activityDefinitions.map(a=>`<button class="activity" data-action="go:${a.id}"><div class="row between"><span class="symbol">${icon(a.icon)}</span>${badge(a.id)}</div><div><h3>${a.name}</h3><p>${({setup:'Parties, roles & transaction details',structure:'3 financing alternatives · compare & decide',kyc:'4 of 5 checks verified · ownership evidence',covenants:'3 clauses extracted · linked to evidence',memo:'AI-assisted draft · ready to develop',credit:'External decision · Credit Committee',product:'Booking preview · follows the live structure',agreement:'Counsel’s draft · compared with agreed terms',closing:'Conditions to close · one owner each',servicing:'Payment and covenant schedule after close'})[a.id]}</p></div><div class="activity-footer"><span class="row"><span class="avatar">${a.owner.split(' ').map(n=>n[0]).slice(0,2).join('')}</span>${a.owner}</span>${icon('arrow')}</div></button>`).join('')}</div><div class="recent"><div class="section-title"><h3>Since you last visited</h3>${btn('go:timeline','View timeline →','link small')}</div>${events(3)}</div>`;}
