// What is true or pending now. Stays in place while the conversation scrolls.
function persistentSummary(){
  const session=sessionOf(view);
  if(session){const done=activityDefinitions.filter(a=>status(a.id,state)[1]==='done').length,mine=session.ownerId===me.id;
    return `<div class="persistent-summary"><div class="row between"><div><strong class="visibility">${icon(session.shared?'users':'lock')}${session.shared?'Shared with the deal team':mine?'Private to you and the agent':'Private'}</strong><small>Project Falcon · ${done} of ${activityDefinitions.length} activities reviewed${session.touched.length?' · touches '+session.touched.map(id=>`<button class="touch-link" data-action="go:${id}">${threadName(id)}</button>`).join(', '):''}</small></div><div class="row">${mine?`<button class="share-switch ${session.shared?'on':''}" role="switch" aria-checked="${session.shared}" data-action="toggleShare"><span class="track"></span>Share with deal team</button>`:`<span class="small">Started by ${first(users[session.ownerId].name)}</span>`}${btn('expandSummary',summaryExpanded?'Collapse':'Deal progress','link','aria-expanded="'+summaryExpanded+'"')}</div></div>${summaryExpanded?`<div class="summary-detail">${renderCard({view:'deal_progress',presentation:'chat_card',stateMode:'live'},viewCtx())}</div>`:''}</div>`;}
  const activity=activityDefinitions.find(a=>a.id===view);if(!activity)return '';
  const c=state.collaboration,pending=view==='structure'?pendingProposals(c):[],known=c.external?.[view];
  const label=view==='structure'?`3 structures · Senior secured ${state.preferred==='a'?'preferred':'working case'} · S + ${c.margin} bps`:view==='memo'?(c.memoStale?'Memo needs an update · pricing changed':`Working draft · ${status('memo',state)[0]}`):`${activity.name} · ${status(view,state)[0]}`;
  const detail=view==='structure'?`Version ${c.objectVersion} · updated by ${first(c.updatedBy)}, ${timeAgo(c.updatedAt)}`:known?`${activity.owner} · ${esc(known.status)} · last known ${timeAgo(known.at)}${Date.now()-known.at>2*864e5?' · may be out of date':''}`:`Owner: ${activity.owner}`;
  return `<div class="persistent-summary"><div class="row between"><div><strong>${label}</strong><small>${detail}${pending.length?` · <button class="summary-flag" data-action="review:${pending[0].id}">${pending.length} change${pending.length>1?'s':''} awaiting review</button>`:''}</small></div>${btn('expandSummary',summaryExpanded?'Collapse':'View current','link','aria-expanded="'+summaryExpanded+'"')}</div>${summaryExpanded?`<div class="summary-detail">${activityContext()}</div>`:''}</div>`;
}
const rich=t=>esc(t).replace(/\*\*(.+?)\*\*/g,'<strong>$1</strong>').replace(/(^|\s)@([A-Z][a-z]+)/g,'$1<span class="mention">@$2</span>').replace(/\n/g,'<br>');
// Humans, the agent and system receipts are distinguishable without being loud.
function messageHtml(m){
  const cards=(m.parts||[]).map(p=>renderCard(p,viewCtx())).join('');
  if(m.kind==='system')return `<div class="system-line">${rich(m.text)} · ${fmtTime(m.ts)}</div>`;
  if(m.kind==='receipt')return cards;
  if(m.kind==='agent')return `<div class="assistant-note ${m.trigger?'agent-update':''}"><span class="assistant-glyph">${icon('spark')}</span><div><div class="message-author">Deal agent<span>${m.trigger?esc(m.trigger)+' · ':''}${fmtTime(m.ts)}</span></div><p>${rich(m.text)}</p>${cards}</div></div>`;
  const u=users[m.authorId]??users.priya;
  return `<article class="team-message"><span class="avatar">${u.name.split(' ').map(x=>x[0]).join('')}</span><div><div class="message-author">${u.name}${u.id===me.id?' (you)':''}<span>${u.title} · ${fmtTime(m.ts)}</span></div><p>${rich(m.text)}</p>${m.object?`<button class="object-link" data-action="focus:${esc(m.object)}">${esc(m.object)}</button>`:''}${cards}</div></article>`;
}
// What happened, what was proposed, and why: one shared, attributed history per activity.
function thread(){
  const c=state.collaboration;anchors[view]??={from:readCursor(c,me.id,view),to:threadMessages(state,view).at(-1)?.ts??0};const anchor=anchors[view].from,opened=anchors[view].to;
  let all=threadMessages(state,view);if(focusObject)all=all.filter(m=>m.object===focusObject);
  // Only what was waiting when the thread was opened counts as unread; live arrivals do not.
  const unread=all.filter(m=>m.ts>anchor&&m.ts<=opened&&m.authorId!==me.id);
  const shown=all.slice(-Math.max(historyCount,unread.length+4)),hidden=all.length-shown.length;
  const digest=!catchUpDismissed[view]&&!focusObject&&catchUp(state,me.id,view,anchor),summary=digest&&digest.lines.some(l=>!l.other)?digest:null;
  const boundary=`<div id="unreadBoundary" class="unread-boundary">Unread · ${unread.length} update${unread.length>1?'s':''} since your last visit</div>${summary?`<div class="catch-up"><strong>Since your last visit</strong><ul>${summary.lines.map(l=>`<li>${esc(l.text)}${l.proposalId&&l.status==='pending'?' '+btn('review:'+l.proposalId,'Review','link'):''}</li>`).join('')}</ul>${btn('dismissCatchUp','Dismiss summary','link')}</div>`:''}`;
  const others=['priya','arjun','meera'].filter(id=>id!==me.id&&isOnline(id)).map(id=>`${first(users[id].name)} is here`).join(' · ');
  return `<div class="team-session"><span>${sessionOf(view)&&!sessionOf(view).shared?icon('lock')+' Private · only you and the agent can see this':icon('users')+' Shared with Priya, Arjun & Meera'}</span><span>${others||'Shared history'}</span></div>${focusObject?`<div class="focus-bar"><span>Showing discussion about <strong>${esc(focusObject)}</strong></span>${btn('focus:','Show all messages','link')}</div>`:''}${hidden?btn('older',`Load older messages (${hidden} more)`,'older-messages'):all.length>8?'<div class="conversation-date">Beginning of shared history</div>':''}${shown.map(m=>(m===unread[0]?boundary:'')+messageHtml(m)).join('')}${streaming[view]?`<div class="assistant-note"><span class="assistant-glyph">${icon('spark')}</span><div><div class="message-author">Deal agent</div><p id="streamingText">${rich(streaming[view].text)}</p></div></div>`:''}${agentStatus[view]?`<div class="agent-status">${icon('spark')}<span>${esc(agentStatus[view])}</span></div>`:''}`;
}
// Where a proposal is inspected, compared with the current version, and decided.
function pricingReview(){
  const c=state.collaboration,p=c.proposals.find(x=>x.id===reviewId);if(!p)return '<h2>Proposal unavailable</h2>';
  const allowed=can(me,'decide'),stale=p.status==='pending'&&reviewVersion!==c.objectVersion,since=changesSince(c,reviewVersion),review=c.reviews.find(r=>r.proposalId===p.id);
  const names=p.affects.map(id=>activityDefinitions.find(a=>a.id===id)?.name.toLowerCase()).join(', ');
  const decide=p.status!=='pending'?`<div class="attention">${icon('info')}<div><strong>This proposal is ${p.status}</strong><p>The original proposal is kept in the conversation.</p></div></div>${btn('work:structure','View current structure','primary')}`:stale?btn('refreshReview','Review latest version','primary'):`<div class="row">${btn('acceptPricing',p.changes.length>1?`Accept ${p.changes.length} changes`:`Accept ${formatTerm(p.changes[0].field,p.changes[0].to)}`,'primary',allowed.ok?'':'disabled')}${btn('rejectPricing','Keep current terms','',allowed.ok?'':'disabled')}</div>${allowed.ok?'':`<p class="small" style="margin-top:10px">${allowed.reason} You can compare the change; the decision is ${first(users.priya.name)}’s.</p>`}`;
  return `<h2>Review ${esc(p.title.toLowerCase())}</h2><p class="small">${review?`Assigned to ${first(users[review.assignee].name)} by ${first(users[review.requestedBy]?.name??p.author)} · `:''}${esc(p.object)} · proposed by ${esc(p.author)}</p>${stale?`<div class="attention" role="alert">${icon('info')}<div><strong>This structure has changed</strong><p>${since.map(x=>`${first(x.by)} changed ${x.label.toLowerCase()} ${formatTerm(x.field,x.from)} → ${formatTerm(x.field,x.to)}`).join('. ')||'It was updated'} while you were reviewing. Compare against version ${c.objectVersion} before deciding.</p></div></div>`:reviewWarning?`<div class="attention" role="alert">${reviewWarning}</div>`:''}<div class="table-wrap"><table class="compare-table"><thead><tr><th>Term</th><th>Current · v${c.objectVersion}</th><th>Proposed</th></tr></thead><tbody>${p.changes.map(x=>`<tr><td>${x.label}</td><td>${formatTerm(x.field,c[x.field])}</td><td><strong>${formatTerm(x.field,x.to)}</strong>${c[x.field]!==x.from&&p.status==='pending'?`<small>written against ${formatTerm(x.field,x.from)}</small>`:''}</td></tr>`).join('')}</tbody></table></div><div class="quote">“${esc(p.quote)}”<p class="small">${esc(p.source)}</p></div><p class="small" style="margin:20px 0">Accepting updates the shared structure, records your decision and flags what depends on it: ${names}. It does not rewrite the memo or grant credit approval.</p>${decide}${p.status==='pending'?`<div class="simulation-control">${btn('simulateEdit','Simulate a teammate edit during review','link small')}<p class="small">Demo only · Arjun changes the current margin to 310 bps to test stale review protection.</p></div>`:''}`;
}
