app.addEventListener('click',async e=>{const b=e.target.closest('[data-action]');if(!b){if(e.target.classList.contains('drawer-backdrop'))closeDrawer();return;}const a=b.dataset.action;if(a.startsWith('go:'))return navigate(a.slice(3));if(a.startsWith('review:'))return openReview(a.slice(7));if(a.startsWith('focus:')){focusObject=a.slice(6)||null;scrollPositions[view]=undefined;jumpLatest=true;return render();}if(a.startsWith('prompt:'))return ask(a.slice(7));if(a.startsWith('as:')){me=users[a.slice(3)];anchors={};catchUpDismissed={};scrollPositions={};newCount=0;drawer=null;history.replaceState(null,'',`?as=${me.id}${location.hash}`);announce();transport.send(envelope('session.open',{dealId:'falcon',userId:me.id}));notify(`Now viewing as ${me.name}, ${me.title.toLowerCase()}.`);return render();}if(a.startsWith('done:')){const r=state.collaboration.reviews.find(x=>x.id===a.slice(5));if(r)r.status='done';save();return render();}if(a.startsWith('sim:'))return simulate(a.slice(4));{const rule={prefer:'prefer',margin:'decide',approveMemo:'approveMemo',requestCredit:'requestCredit',submitBooking:'submitBooking',acceptDeviation:'acceptDeviation',signFeeLetter:'signFeeLetter',verifyKyc:'verifyKyc'}[a];if(rule&&!can(me,rule).ok)return notify(can(me,rule).reason);}if(a.startsWith('work:')){surfaceId=a.slice(5);workspaceOpen=true;drawer=null;render();return;}if(a.startsWith('select:')){selected=a.slice(7);return render();}if(a.startsWith('other:')){drawer=a;if(markRead(state.collaboration,me.id,'project:'+a.slice(6),Date.now()))save();return render();}if(a.startsWith('ask:'))return ask(a.endsWith('blockers')?'What is blocking this deal?':'What changed since my last visit?');switch(a){case 'demo':navigate('structure');break;case 'newSession':{const id='s:'+uid('c');state.collaboration.sessions.push({id,title:'New conversation',ownerId:me.id,shared:false,createdAt:Date.now(),touched:[]});save();navigate(id);app.querySelector('#chatInput')?.focus();break;}case 'toggleShare':{const x=sessionOf(view);if(!x||x.ownerId!==me.id)break;x.shared=!x.shared;arrive(view,{role:'assistant',kind:'system',authorId:me.id,text:x.shared?`${first(me.name)} shared this conversation with the deal team`:`${first(me.name)} made this conversation private`});save();render();notify(x.shared?'Shared. The deal team can now see and join this conversation.':'Private again. Only you and the agent can see it.');break;}case 'toggleActivities':activitiesCollapsed=!activitiesCollapsed;try{localStorage.setItem('mandate-rail-activities',activitiesCollapsed?'collapsed':'open');}catch{}render();break;case 'allSessions':lastFocus=b;drawer='sessions';render();break;case 'toggleProject':railCollapsed=!railCollapsed;try{localStorage.setItem('mandate-rail',railCollapsed?'collapsed':'open');}catch{}render();break;case 'toggleAgent':askAgent=!askAgent;render();break;case 'scenarios':lastFocus=b;drawer='scenarios';render();break;case 'bookingConfirm':lastFocus=b;drawer='booking';render();break;case 'submitBooking':drawer=null;state.collaboration.external.product={status:'Booking received by Loan Ops',at:Date.now(),source:'Simulated ledger receipt'};dispatch('submitBooking');notify('Booking submitted to the simulated ledger.');break;case 'acceptDeviation':dispatch('acceptDeviation');notify('Deviation accepted and recorded.');break;case 'signFeeLetter':dispatch('signFeeLetter');notify('Signed fee letter recorded.');break;case 'verifyKyc':dispatch('verifyKyc');notify('Ownership evidence verified.');break;case 'expandSummary':summaryExpanded=!summaryExpanded;render();break;case 'older':{const el=app.querySelector('.message-scroll'),height=el.scrollHeight,top=el.scrollTop;historyCount+=8;render();const next=app.querySelector('.message-scroll');next.scrollTop=top+next.scrollHeight-height;break;}case 'latest':{const el=app.querySelector('.message-scroll');newCount=0;el.scrollTop=el.scrollHeight;break;}case 'unread':app.querySelector('#unreadBoundary')?.scrollIntoView({block:'start'});break;case 'dismissCatchUp':catchUpDismissed[view]=true;render();break;case 'refreshReview':reviewVersion=state.collaboration.objectVersion;reviewWarning='';render();break;case 'simulateEdit':simulateEdit();break;case 'acceptPricing':case 'rejectPricing':{const accept=a==='acceptPricing',result=resolvePricing(state.collaboration,accept?'accept':'reject',reviewVersion,{proposalId:reviewId,user:me});if(!result.ok){reviewWarning=result.reason;render();break;}state.collaboration=result.state;const d=result.decision,title=state.collaboration.proposals.find(p=>p.id===d.proposalId).title.toLowerCase();if(accept){state.marginConfirmed=true;state.memoApproved=false;}state.events.unshift({label:`${first(me.name)} ${accept?'accepted':'rejected'} ${title}${accept?'; memo needs an update':''}`,time:new Date().toISOString()});arrive('structure',{role:'assistant',kind:'receipt',authorId:me.id,text:'',object:'Structure A',parts:[{view:'decision_receipt',decisionId:d.id,presentation:'chat_card',stateMode:'snapshot'}]});if(sessionOf(view))arrive(view,{role:'assistant',kind:'receipt',authorId:me.id,text:'',parts:[{view:'decision_receipt',decisionId:d.id,presentation:'chat_card',stateMode:'snapshot'}]});save();drawer=null;jumpLatest=view==='structure'||Boolean(sessionOf(view));render();notify('Decision recorded. Historical proposal retained.');transport.send(envelope('ui.action',{action:accept?'proposal.accepted':'proposal.rejected',userId:me.id,targetId:d.proposalId,result:{version:d.version}}));break;}case 'menu':menu=!menu;render();break;case 'toggleChat':case 'returnChat':workspaceOpen=false;surfaceId=null;render();break;case 'progress':lastFocus=b;drawer='progress';render();break;case 'source':case 'help':lastFocus=b;drawer=a;render();break;case 'closeDrawer':closeDrawer();break;case 'prefer':dispatch('prefer',selected);notify('Preferred structure selected. Memo approval must be renewed after changes.');break;case 'margin':dispatch('margin');notify('Margin confirmed and recorded in the timeline.');break;case 'reviewCovenants':dispatch('covenants');notify('Extraction reviewed. Legal approval remains separate.');break;case 'requestDraft':lastFocus=b;drawer='request';render();break;case 'requestKyc':drawer=null;dispatch('requestKyc');notify('Marked as requested. No message was sent.');break;case 'receiveKyc':dispatch('receiveKyc');notify('Sample evidence received. Verification remains pending.');break;case 'copyRequest':try{await navigator.clipboard.writeText(document.querySelector('#requestText').value);notify('Draft copied.');}catch{notify('Select and copy the draft text manually.');}break;case 'saveMemo':dispatch('memo',document.querySelector('#memoText').value);notify('Draft saved locally.');break;case 'generate':transport.send(envelope('action.request',{action:'memo.refresh',threadId:'memo',userId:me.id,args:{text:document.querySelector('#memoText').value}}));notify('The agent is refreshing the recommendation. Review it before approving.');break;case 'approveMemo':{const text=document.querySelector('#memoText').value;if(text!==state.memo)state=reduce(state,'memo',text);dispatch('approveMemo');notify('Memo approved and recorded.');break;}case 'requestCredit':state.collaboration.external.credit={status:'Pack with the committee secretary',at:Date.now(),source:'Submission receipt'};dispatch('requestCredit');notify('Submitted to simulated credit queue. Approval is pending.');break;case 'downloadMemo':{const blob=new Blob([document.querySelector('#memoText').value],{type:'text/plain'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='Falcon-credit-memo.txt';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);break;}case 'upload':document.querySelector('#fileInput').click();break;}});
function simulateEdit(){const c=state.collaboration;if(c.margin===310)return notify('The margin is already 310 bps.');state.collaboration=editTerm(c,'margin',310,users.arjun);arrive('structure',{role:'assistant',kind:'system',authorId:'arjun',text:`Arjun changed Structure A margin ${formatTerm('margin',c.margin)} → 310 bps · now version ${state.collaboration.objectVersion}`,object:'Structure A'});save();render();}
function simulate(name){drawer=null;if(['termsheet','committee','legal'].includes(name)&&!transport.simulate){render();return notify('Scenarios that involve the agent need the demo agent.');}switch(name){case 'message':{const who=me.id==='meera'?'arjun':'meera';arrive(view,{role:'user',kind:'user',authorId:who,text:who==='meera'?'Quick update: the client’s counsel says the ownership declaration will be countersigned tomorrow.':'I’ve refreshed the comparable pricing table with last week’s two logistics deals.'});save();render();break;}case 'edit':simulateEdit();break;case 'osprey':{const who=me.id==='arjun'?'meera':'arjun';(state.collaboration.projectActivity??={}).Osprey={at:Date.now(),by:who};save();render();notify(`${first(users[who].name)} commented on Project Osprey.`);break;}case 'termsheet':arrive('structure',{role:'user',kind:'user',authorId:'arjun',text:'Uploaded **Term_Sheet_v4.pdf** from the client’s counsel. Asking the agent to compare it with what we have confirmed.',object:'Structure A'});save();render();transport.simulate('term_sheet_v4');break;case 'committee':render();transport.simulate('committee_decision');break;case 'legal':render();transport.simulate('legal_draft');break;case 'reset':localStorage.removeItem('mandate-v1');location.href=location.pathname+location.search;break;}}
