app.addEventListener('keydown',e=>{if(e.target.id==='chatInput'&&e.key==='Enter'&&!e.shiftKey){e.preventDefault();const v=e.target.value.trim();if(v)ask(v);return;}if(!drawer){if(e.key==='Escape'&&workspaceOpen){workspaceOpen=false;render();}return;}if(e.key==='Escape')closeDrawer();if(e.key==='Tab'){const els=[...document.querySelector('.drawer').querySelectorAll('button:not(:disabled),textarea,a,input')];const first=els[0],last=els.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}});window.addEventListener('hashchange',()=>{view=location.hash.slice(1)||'overview';if(view==='chat')view='overview';render();});
